Dataspatium.assets.register("presets/api/fhm-folkhalsodata.api.json","text","{\n  \"format\": \"dataspatium-api/1\",\n  \"id\": \"fhm-folkhalsodata\",\n  \"name\": \"Folkhälsomyndigheten Folkhälsodata\",\n  \"publisher\": \"Folkhälsomyndigheten\",\n  \"description\": \"Folkhälsostatistik: nationella folkhälsoenkäten, skolbarns hälsovanor, smittsamma sjukdomar, vaccinationer, ANDTS-indikatorer, antibiotika med mera. Bläddra i ämnesträdet, välj tabell och värden per variabel (PxWeb).\",\n  \"docs\": \"https://www.folkhalsomyndigheten.se/folkhalsorapportering-statistik/statistikdatabaser-och-visualisering/folkhalsodata/\",\n  \"license\": { \"name\": \"Fri användning med källhänvisning, se Folkhälsomyndighetens villkor\", \"url\": \"https://www.folkhalsomyndigheten.se/om-webbplatsen/\" },\n  \"level\": 1,\n  \"country\": \"SE\",\n  \"baseUrl\": \"https://fohm-app.folkhalsomyndigheten.se/Folkhalsodata/api/v1/sv/A_Folkhalsodata\",\n  \"auth\": { \"type\": \"none\" },\n  \"rateLimit\": { \"requests\": 30, \"perSeconds\": 10 },\n  \"family\": { \"type\": \"pxweb\", \"version\": 1, \"maxCells\": 100000 },\n  \"endpoints\": [\n    {\n      \"id\": \"folder\",\n      \"name\": \"Lista innehållet i en mapp\",\n      \"description\": \"Mappar och tabeller under en sökväg, till exempel B_HLV. Tom sökväg ger ämnesområdena.\",\n      \"method\": \"GET\",\n      \"path\": \"/{path}/\",\n      \"params\": [\n        { \"name\": \"path\", \"in\": \"path\", \"label\": \"Sökväg\", \"type\": \"string\", \"raw\": true, \"example\": \"B_HLV\" }\n      ],\n      \"response\": { \"format\": \"json\" },\n      \"dataset\": { \"name\": \"Folkhälsodata mapp {path}\" }\n    }\n  ],\n  \"i18n\": {\n    \"en\": {\"name\": \"Public Health Agency of Sweden: Folkhälsodata\", \"publisher\": \"Public Health Agency of Sweden (Folkhälsomyndigheten)\", \"description\": \"Public health statistics: the national public health survey, schoolchildren's health habits, communicable diseases, vaccinations, indicators for alcohol, narcotics, doping, tobacco and gambling, antibiotics and more. Browse the subject tree, pick a table and values per variable (PxWeb).\", \"endpoints\": {\"folder\": {\"name\": \"List the contents of a folder\", \"description\": \"Folders and tables under a path, for example B_HLV. An empty path gives the subject areas.\", \"params\": {\"path\": {\"label\": \"Path\"}}}}, \"dataset\": {\"folder\": \"Folkhälsodata folder {path}\"}},\n    \"da\": {\"name\": \"Folkhälsomyndigheten Folkhälsodata\", \"publisher\": \"Folkhälsomyndigheten (Sveriges folkesundhedsmyndighed)\", \"description\": \"Svensk folkesundhedsstatistik: den nationale folkesundhedsundersøgelse, skolebørns sundhedsvaner, smitsomme sygdomme, vaccinationer, indikatorer for alkohol, narkotika, doping, tobak og spil, antibiotika med mere. Gennemse emnetræet, vælg tabel og værdier pr. variabel (PxWeb).\", \"endpoints\": {\"folder\": {\"name\": \"Vis indholdet i en mappe\", \"description\": \"Mapper og tabeller under en sti, for eksempel B_HLV. En tom sti giver emneområderne.\", \"params\": {\"path\": {\"label\": \"Sti\"}}}}, \"dataset\": {\"folder\": \"Folkhälsodata mappe {path}\"}},\n    \"nb\": {\"name\": \"Folkhälsomyndigheten Folkhälsodata\", \"publisher\": \"Folkhälsomyndigheten (Sveriges folkehelsemyndighet)\", \"description\": \"Svensk folkehelsestatistikk: den nasjonale folkehelseundersøkelsen, skolebarns helsevaner, smittsomme sykdommer, vaksinasjoner, indikatorer for alkohol, narkotika, doping, tobakk og pengespill, antibiotika med mer. Bla i emnetreet, velg tabell og verdier per variabel (PxWeb).\", \"endpoints\": {\"folder\": {\"name\": \"List innholdet i en mappe\", \"description\": \"Mapper og tabeller under en sti, for eksempel B_HLV. En tom sti gir emneområdene.\", \"params\": {\"path\": {\"label\": \"Sti\"}}}}, \"dataset\": {\"folder\": \"Folkhälsodata mappe {path}\"}},\n    \"fi\": {\"name\": \"Ruotsin kansanterveysvirasto: Folkhälsodata\", \"publisher\": \"Folkhälsomyndigheten (Ruotsin kansanterveysvirasto)\", \"description\": \"Ruotsin kansanterveystilastot: kansallinen terveyskysely, koululaisten terveystottumukset, tartuntataudit, rokotukset, alkoholi-, huume-, doping-, tupakka- ja rahapeli-indikaattorit, antibiootit ja muuta. Selaa aihepuuta, valitse taulukko ja arvot muuttujittain (PxWeb).\", \"endpoints\": {\"folder\": {\"name\": \"Luettele kansion sisältö\", \"description\": \"Kansiot ja taulukot polun alla, esimerkiksi B_HLV. Tyhjä polku antaa aihealueet.\", \"params\": {\"path\": {\"label\": \"Polku\"}}}}, \"dataset\": {\"folder\": \"Folkhälsodata kansio {path}\"}},\n    \"is\": {\"name\": \"Lýðheilsustofnun Svíþjóðar: Folkhälsodata\", \"publisher\": \"Folkhälsomyndigheten (Lýðheilsustofnun Svíþjóðar)\", \"description\": \"Sænskar lýðheilsutölur: landskönnun á lýðheilsu, heilsuvenjur skólabarna, smitsjúkdómar, bólusetningar, vísar um áfengi, fíkniefni, lyfjamisnotkun, tóbak og fjárhættuspil, sýklalyf og fleira. Flettu í efnistrénu, veldu töflu og gildi fyrir hverja breytu (PxWeb).\", \"endpoints\": {\"folder\": {\"name\": \"Sýna innihald möppu\", \"description\": \"Möppur og töflur undir slóð, til dæmis B_HLV. Auð slóð gefur efnissviðin.\", \"params\": {\"path\": {\"label\": \"Slóð\"}}}}, \"dataset\": {\"folder\": \"Folkhälsodata mappa {path}\"}}\n  }\n}\n");
